<?php
namespace App\Models\Institution;
use Core\Helpers\ActorHelper;use Core\Helpers\UuidHelper;use PDO;
class EmploymentRuleModel{public function __construct(private PDO $db){}public function page(array $q):array{$p=[];$w=['r.deleted_at IS NULL','v.deleted_at IS NULL'];$f=json_decode((string)($q['filters']??'[]'),true);foreach(is_array($f)?$f:[]as$x){$k=(string)($x['field']??'');$v=trim((string)($x['value']??''));if($v==='')continue;if($k==='rule_type_code'){$w[]='r.rule_type_code=:t';$p[':t']=$v;}elseif($k==='status_code'){$w[]='v.status_code=:s';$p[':s']=$v;}}$search=trim((string)($q['search']['value']??''));if($search!==''){$w[]='(r.rule_code LIKE :q OR r.title LIKE :q OR v.revision_title LIKE :q)';$p[':q']='%'.$search.'%';}$from=' FROM institution_employment_rules r JOIN institution_employment_rules_revisions v ON v.rule_id=r.id WHERE '.implode(' AND ',$w);$c=$this->db->prepare('SELECT COUNT(*)'.$from);$c->execute($p);$start=max(0,(int)($q['start']??0));$len=max(1,min(200,(int)($q['length']??50)));$s=$this->db->prepare('SELECT r.id rule_id,r.rule_code,r.rule_type_code,r.title,r.description,r.is_active,v.*'.$from.' ORDER BY r.title,v.revision_no DESC LIMIT '.$start.','.$len);$s->execute($p);return['rows'=>ActorHelper::enrichActorNames($s->fetchAll(PDO::FETCH_ASSOC)?:[],['created_by','updated_by','approved_by','published_by']),'total'=>(int)$c->fetchColumn()];}public function detail(string $id,bool $lock=false):?array{$s=$this->db->prepare('SELECT r.id rule_id,r.rule_code,r.rule_type_code,r.title,r.description,r.company_id,r.owner_department_id,r.current_revision_id,r.is_active,v.* FROM institution_employment_rules r JOIN institution_employment_rules_revisions v ON v.rule_id=r.id WHERE v.id=:id AND r.deleted_at IS NULL AND v.deleted_at IS NULL'.($lock?' FOR UPDATE':''));$s->execute([':id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)return null;$r['items']=$this->rows('SELECT * FROM institution_employment_rules_items WHERE revision_id=:id ORDER BY sort_no',[':id'=>$id]);$r['scopes']=$this->rows('SELECT * FROM institution_employment_rules_scopes WHERE revision_id=:id',[':id'=>$id]);return ActorHelper::enrichActorNamesRow($r,['created_by','updated_by','approved_by','published_by']);}public function history(string$id):array{return ActorHelper::enrichActorNames($this->rows('SELECT * FROM institution_employment_rules_revisions WHERE rule_id=:id AND deleted_at IS NULL ORDER BY revision_no DESC',[':id'=>$id]),['created_by','updated_by','approved_by','published_by']);}public function findRevisionByRequestKey(string$key):?string{$s=$this->db->prepare('SELECT id FROM institution_employment_rules_revisions WHERE request_key=:k AND deleted_at IS NULL LIMIT 1');$s->execute([':k'=>$key]);$id=$s->fetchColumn();return$id?(string)$id:null;}public function create(string $table,array $d):string{$id=UuidHelper::generate();$d=['id'=>$id]+$d;$f=array_keys($d);$s=$this->db->prepare('INSERT INTO '.$table.'('.implode(',',$f).')VALUES(:'.implode(',:',$f).')');$s->execute(array_combine(array_map(fn($x)=>':'.$x,$f),array_values($d)));return$id;}public function update(string $table,string $id,array $d):void{$p=[':id'=>$id];$set=[];foreach($d as$k=>$v){$set[]=$k.'=:'.$k;$p[':'.$k]=$v;}$s=$this->db->prepare('UPDATE '.$table.' SET '.implode(',',$set).' WHERE id=:id');$s->execute($p);}public function deleteChildren(string $revision):void{$this->db->prepare('DELETE FROM institution_employment_rules_items WHERE revision_id=:id')->execute([':id'=>$revision]);$this->db->prepare('DELETE FROM institution_employment_rules_scopes WHERE revision_id=:id')->execute([':id'=>$revision]);}public function nextRevision(string $rule):int{$s=$this->db->prepare('SELECT COALESCE(MAX(revision_no),0)+1 FROM institution_employment_rules_revisions WHERE rule_id=:id');$s->execute([':id'=>$rule]);return(int)$s->fetchColumn();}public function code(string $g,string $c):bool{$s=$this->db->prepare('SELECT COUNT(*) FROM system_codes WHERE code_group=:g AND code=:c AND is_active=1');$s->execute([':g'=>$g,':c'=>$c]);return(bool)$s->fetchColumn();}public function options(string $g):array{$s=$this->db->prepare('SELECT code value,code_name label FROM system_codes WHERE code_group=:g AND is_active=1 ORDER BY sort_no');$s->execute([':g'=>$g]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}public function expireCurrentRevision(string$rule,string$except,string$from,string$actor,string$now):void{$s=$this->db->prepare("UPDATE institution_employment_rules_revisions SET status_code='EXPIRED',effective_to=DATE_SUB(:d,INTERVAL 1 DAY),updated_at=:now,updated_by=:actor WHERE rule_id=:r AND id<>:id AND status_code='EFFECTIVE' AND (effective_to IS NULL OR effective_to>=:d)");$s->execute([':d'=>$from,':now'=>$now,':actor'=>$actor,':r'=>$rule,':id'=>$except]);}public function softDeleteRevision(string$id,string$actor):void{$s=$this->db->prepare('UPDATE institution_employment_rules_revisions SET deleted_at=NOW(),deleted_by=:a,updated_at=NOW(),updated_by=:a WHERE id=:id');$s->execute([':a'=>$actor,':id'=>$id]);}public function rows(string $sql,array $p=[]):array{$s=$this->db->prepare($sql);$s->execute($p);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}}
